// Located in: frontend/src/App.js

// This is the constant defining the target server address.
const API_BASE_URL = 'http://localhost:9091/api/medicines'; 

// ... later in the code, the React app uses this URL:
const fetchMedicines = useCallback(async () => {
    const data = await fetchData(API_BASE_URL); // <-- The request goes to 9091!
    // ...
}, [fetchData]);

import React, { useEffect, useState } from "react";

function App() {
  const [medicines, setMedicines] = useState([]);

  useEffect(() => {
    fetch("http://localhost:9091/api/medicines")
      .then((response) => response.json())
      .then((data) => setMedicines(data))
      .catch((error) => console.error("Error fetching medicines:", error));
  }, []);

  return (
    <div style={{ padding: "20px", fontFamily: "Arial" }}>
      <h1>💊 Medicine Inventory</h1>
      <table
        border="1"
        cellPadding="10"
        style={{ borderCollapse: "collapse", width: "100%", textAlign: "left" }}
      >
        <thead style={{ backgroundColor: "#f2f2f2" }}>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Description</th>
            <th>Price (₹)</th>
            <th>Stock</th>
          </tr>
        </thead>
        <tbody>
          {medicines.map((med) => (
            <tr key={med.id}>
              <td>{med.id}</td>
              <td>{med.name}</td>
              <td>{med.description}</td>
              <td>{med.price}</td>
              <td>{med.stock}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default App;
